CREATE TABLE `T_CK_CT_MST_SAGE_INT_STATE` (
  `SIS_ID` varchar(35) NOT NULL COMMENT 'SAGE INTEGRATION STATE ID - SUBMITTED:PARTIAL:SUCCESS',
  `SIS_NAME` varchar(100) NOT NULL COMMENT 'SAGE INTEGRATION STATE NAME',
  `SIS_DESC` varchar(255) DEFAULT NULL COMMENT 'SAGE INTEGRATION STATE DESCRIPTION',
  `SIS_DESC_OTH` varchar(512) DEFAULT NULL COMMENT 'SAGE INTEGRATION STATE DESCRIPTION OTHER LANGUAGE',
  `SIS_STATUS` char(1) DEFAULT NULL COMMENT 'SAGE INTEGRATION STATE STATUS',
  `SIS_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SIS_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SIS_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SIS_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SIS_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SAGE INTEGRATION STATE MASTER TABLE';

CREATE TABLE `T_CK_CT_MST_SAGE_INT_TYPE` (
  `SIT_ID` varchar(35) NOT NULL COMMENT 'SAGE INTEGRATION TYPE ID - BOOKING:PAYMENT_IN:PAYMENT_OUT',
  `SIT_NAME` varchar(100) NOT NULL COMMENT 'SAGE INTEGRATION TYPE NAME',
  `SIT_DESC` varchar(255) DEFAULT NULL COMMENT 'SAGE INTEGRATION TYPE DESCRIPTION',
  `SIT_DESC_OTH` varchar(512) DEFAULT NULL COMMENT 'SAGE INTEGRATION TYPE DESCRIPTION OTHER LANGUAGE',
  `SIT_STATUS` char(1) DEFAULT NULL COMMENT 'SAGE INTEGRATION TYPE STATUS',
  `SIT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SIT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SIT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SIT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SIT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SAGE INTEGRATION TYPE MASTER TABLE';


CREATE TABLE `T_CK_SAGE_INTEGRATION` (
  `SINT_ID` varchar(35) NOT NULL COMMENT 'SAGE INTEGRATION RECORD ID - UUID',
  `SINT_SVC` varchar(35) DEFAULT NULL COMMENT 'CLICKARGO SERVICES - REFERENCE T_CK_MST_SERVICE_TYPE:SVCT_ID',  
  `SINT_STATE` varchar(35) NOT NULL COMMENT 'SAGE INTEGRATION STATE - REFERENCES T_CK_CT_MST_SAGE_INT_STATE:SIS_ID',
  `SINT_INT_TYPE` varchar(35) DEFAULT NULL COMMENT 'INTEGRATION - REFERENCES T_CK_CT_MST_SAGE_INT_TYPE:SIT_ID',
  `SINT_DT_START` datetime DEFAULT NULL COMMENT 'SAGE INTEGRATION START DATE TIME',
  `SINT_DT_END` datetime DEFAULT NULL COMMENT 'SAGE INTEGRATION END DATE TIME',
  `SINT_NO_RECORDS` mediumint DEFAULT 0 COMMENT 'SAGE INTEGRATION NUMBER OF RECORDS',
  `SINT_NO_SUCCESS` mediumint DEFAULT 0 COMMENT 'SAGE INTEGRATION NUMBER OF SUCCESS RECORDS',
  `SINT_NO_FAIL` mediumint DEFAULT 0 COMMENT 'SAGE INTEGRATION NUMBER OF FAIL RECORDS',
  `SINT_DT_EXPORT` datetime DEFAULT NULL COMMENT 'SAGE INTEGRATION EXPORT DATE',
  `SINT_DT_IMPORT` datetime DEFAULT NULL COMMENT 'SAGE INTEGRATION IMPORT DATE',
  `SINT_LOC_EXPORT` varchar(1024) DEFAULT NULL COMMENT 'PHYSICAL LOCATION OF THE EXPORT EXCEL FILE FROM  CLICTRCUK',
  `SINT_LOC_IMPORT` varchar(1024) DEFAULT NULL COMMENT 'PHYSICAL LOCATION OF THE IMPORT EXCEL FILE FROM SAGE',
  `SINT_STATUS` char(1) DEFAULT NULL COMMENT 'VEHICLE STATE STATUS',
  `SINT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SINT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SINT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SINT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SINT_ID`),
	CONSTRAINT `FK_CK_SAGE_INTEGRARTION_CK_MST_SERVICE_TYPE` FOREIGN KEY (`SINT_SVC`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_SAGE_INTEGRARTION_CK_CT_MST_SAGE_INT_STATE` FOREIGN KEY (`SINT_STATE`) REFERENCES `T_CK_CT_MST_SAGE_INT_STATE` (`SIS_ID`),  
  CONSTRAINT `FK_CK_SAGE_INTEGRARTION_CK_CT_MST_SAGE_INT_TYPE` FOREIGN KEY (`SINT_INT_TYPE`) REFERENCES `T_CK_CT_MST_SAGE_INT_TYPE` (`SIT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SAGE INTEGRATION MAINTENACNE TABLE';

