CREATE TABLE `T_CK_CT_MST_TRACK_DEVICE_STATE` (
  `TDS_ID` varchar(35) NOT NULL COMMENT 'TRACK DEVICE STATE ID - NEW:ACTIVATE:DEACTIVATE',
  `TDS_NAME` varchar(100) NOT NULL COMMENT 'TRACK DEVICE STATE NAME',
  `TDS_DESC` varchar(255) DEFAULT NULL COMMENT 'TRACK DEVICE STATE DESCRIPTION',
  `TDS_DESC_OTH` varchar(512) DEFAULT NULL COMMENT 'TRACK DEVICE STATE DESCRIPTION OTHER LANGUAGE',
  `TDS_STATUS` char(1) DEFAULT NULL COMMENT 'TRACK DEVICE STATE STATUS',
  `TDS_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `TDS_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `TDS_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `TDS_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TDS_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TRACK DEVICE STATE MASTER TABLE';


CREATE TABLE `T_CK_CT_TRACK_DEVICE` (
  `TD_ID` varchar(35) NOT NULL COMMENT 'TRACKING DEVICE RECORD ID - UUID',
  `TD_STATE` varchar(35) NOT NULL COMMENT 'TRACKING DEVICE STATE - REFERENCES T_CK_CT_MST_TRACK_DEVICE_STATE:TDS_ID',
  `TD_VEH_ID` varchar(35) DEFAULT NULL COMMENT 'VEHICLE TYPE - REFERENCES T_CK_CT_VEH:VH_ID',
  `TD_VEH_PLATE_NO` varchar(256) DEFAULT NULL COMMENT 'VEHICLE PLATE NUMBER',
  `TD_COMPANY` varchar(35) DEFAULT NULL COMMENT 'COMPANY  - REFERENCES T_CORE_ACCN:ACCN_ID',
  `TD_COMPANY_TYPE` varchar(35) DEFAULT NULL COMMENT 'COMAPNY TYPE - REFERENCES T_MST_ACCN_TYPE:ATYP_ID',
  `TD_GPS_IMEI` varchar(1024) DEFAULT NULL COMMENT 'GPS IMEI ASSIGNED TO TRUCK',
  `TD_DT_ACTIVATTION` datetime DEFAULT NULL COMMENT 'ACTIVATION DATE IS AFTER INSTALLATION THEN WE TELL ASCENT THEN ASCENT TELLS US WHEN IT IS ACTIVATED',
  `TD_DT_ACTIVATE` datetime DEFAULT NULL COMMENT 'TRACKING DEVICE ACTIVATION DATE TIME, WHEN GLI USER CLICK <ACTIVE> BUTTON',
  `TD_DT_DEACTIVATE` datetime DEFAULT NULL COMMENT 'TRACKING DEVICE DEACTIVATION DATE TIME',
  `TD_UID_ACTIVATE` varchar(35) DEFAULT NULL COMMENT 'TRACKING DEVICE ACTIVATION BY',
  `TD_UID_DEACTIVATE` varchar(35) DEFAULT NULL COMMENT 'TRACKING DEVICE DEACTIVATION BY',
  `TD_STATUS` char(1) DEFAULT NULL COMMENT 'VEHICLE STATE STATUS',
  `TD_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `TD_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `TD_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `TD_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TD_ID`),
  CONSTRAINT `FK_CK_CT_TRACK_DEVICE_CK_CT_MST_TRACK_DEVICE_STATE` FOREIGN KEY (`TD_STATE`) REFERENCES `T_CK_CT_MST_TRACK_DEVICE_STATE` (`TDS_ID`),  
  CONSTRAINT `FK_CK_CT_TRACK_DEVICE_CK_CT_VEH` FOREIGN KEY (`TD_VEH_ID`) REFERENCES `T_CK_CT_VEH` (`VH_ID`),
  CONSTRAINT `FK_CK_CT_TRACK_DEVICE_CORE_ACCN` FOREIGN KEY (`TD_COMPANY`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_CT_TRACK_DEVICE_MST_ACCN_TYPE` FOREIGN KEY (`TD_COMPANY_TYPE`) REFERENCES `T_MST_ACCN_TYPE` (`ATYP_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TRACKING DEVICE MAINTENACNE TABLE';

