CREATE TABLE `T_CK_CS_ACCN` (
  `CSA_ID` varchar(35) NOT NULL COMMENT 'RECORD ID - UUID',
  `CSA_SERVICE_TYPE` varchar(35) DEFAULT NULL COMMENT 'SERVICE TYPE - REFERENCES T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `CSA_COMPANY` varchar(35) DEFAULT NULL COMMENT 'COMPANY ACCOUNT - REFERENCES T_CORE_ACCN:ACCN_ID',  
  `CSA_USR` varchar(35) DEFAULT NULL COMMENT 'CUSTOMER SERVICE - REFERENCES T_CORE_USR:USR_UID',  
  `CSA_STATUS` char(1) DEFAULT NULL COMMENT 'CREDIT RECORD STATUS',
  `CSA_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `CSA_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `CSA_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `CSA_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`CSA_ID`),
  CONSTRAINT `FK_CK_CS_ACCN_CK_MST_SERVICE_TYPE` FOREIGN KEY (`CSA_SERVICE_TYPE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_CS_ACCN_CORE_ACCN` FOREIGN KEY (`CSA_COMPANY`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),  
  CONSTRAINT `FK_CK_CS_ACCN_CORE_USR` FOREIGN KEY (`CSA_USR`) REFERENCES `T_CORE_USR` (`USR_UID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='CUSTOMER SERVICE ACCOUNTS TABLE';


