CREATE TABLE `T_CK_CT_MST_ALERT` (
 `ALT_ID` varchar(100) NOT NULL COMMENT 'UNIQUE ID: SYSTEM GENERATED',
 `ALT_NAME` varchar(100) NOT NULL COMMENT 'THE NAME OF THE ALERT. SHOWN TO USERS TO SELECT',
 `ALT_MODULE` varchar(100) NOT NULL COMMENT 'THE MODULE/FEATURE THE ALERT IS RELATED TO. USED TO DEFINE WHICH ALERTS WILL BE SHOWN TO USER WHEN CREATING A NEW ALERT',
 `ALT_NOTIFICATION_TYPE` varchar(100) DEFAULT NULL COMMENT 'THE DEVICE TYPE USED TO SEND THE ALERT',
 `ALT_TEMPLATE_ID` varchar(100) DEFAULT NULL COMMENT 'REFERENCES THE TEMPLATES TO BE USED FOR POPULATING THE ALERT MESSAGE',
 `ALT_CONDITION_TYPE` varchar(100) DEFAULT NULL COMMENT 'THE DIFFERENT CONDITIONS APPLICABLE TO THIS ALERT. USED TO DEFINE WHICH CONDITION TYPES WILL BE SHOWN TO USER WHEN CREATING A NEW ALERT NOTE: WILL BE NULL FOR JOB MODULE ALERTS SINCE THEY ARE TRIGGERED BY JOB EVENTS',
 `ALT_STATUS` char(1) DEFAULT NULL COMMENT 'ACTIVE, INACTIVE',
 `ALT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
 `ALT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
 `ALT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
 `ALT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
 PRIMARY KEY (`ALT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SAGE INTEGRATION STATE MASTER TABLE';

CREATE TABLE `T_CK_CT_ALERT` (
 `ALT_ID` VARCHAR(100) NOT NULL COMMENT 'UNIQUE ID. SYSTEM GENERATED',
 `ALT_ACCN_ID` VARCHAR(35) NOT NULL COMMENT 'ACCOUNT THE ALERT BELONGS TO. REFERENCES T_CORE_ACCN: ACCN_ID',
 `ALT_ALERT_MASTER_TABLE_REF_ID` VARCHAR(100) NOT NULL COMMENT 'REFERENCE ALERT ID FROM ALERT MASTER TABLE. REFERENCES T_CK_CT_MST_ALERT: ALERT ID',
 `ALT_CONDITION_TYPE` varchar(100) NOT NULL COMMENT 'RULE TO CHECK AGAINST TO DECIDE IF THE ALERT IS TRIGGERED. VALUES: DAYS_BEFORE, DISTANCE',
 `ALT_CONDITION_VALUE` varchar(255) DEFAULT NULL COMMENT 'VALUE RELATED TO CONDITION TYPE, E.G., 10',
 `ALT_CONDITION_DATE` DATE DEFAULT NULL COMMENT 'DATE RELATED TO CONDITION TYPE. DISPLAY LABEL: DUE DATE OR EXPIRY DATE. DISPLAY FORMAT: DD/MM/YYYY',
 `ALT_REFERENCE_ID` VARCHAR(35) DEFAULT NULL COMMENT 'THE UNIQUE ID OF THE DRIVER/TRUCK THAT THIS ALERT IS RELATED TO',
 `ALT_RECIPIENT_CONTACT` VARCHAR(100) DEFAULT NULL COMMENT 'CONTACT INFO THAT WILL RECEIVE THE ALERT, E.G., +6512345678 OR TEST@EXAMPLE.COM',
 `ALT_REMARKS` MEDIUMTEXT COMMENT 'REMARKS ENTERED BY USER FOR THIS ALERT, E.G., SPECIFIC PARTS TO TAKE NOTE DURING MAINTENANCE CHECK',
 `ALT_STATUS` CHAR(1) DEFAULT NULL COMMENT 'ACTIVE, INACTIVE',
 `ALT_DT_CREATE` DATETIME DEFAULT NULL COMMENT 'RECORD CREATED DATE',
 `ALT_UID_CREATE` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
 `ALT_DT_LUPD` DATETIME DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
 `ALT_UID_LUPD` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
 PRIMARY KEY (`ALT_ID`),
 FOREIGN KEY (`ALT_ACCN_ID`) REFERENCES `T_CORE_ACCN`(`ACCN_ID`),
 FOREIGN KEY (`ALT_ALERT_MASTER_TABLE_REF_ID`) REFERENCES `T_CK_CT_MST_ALERT`(`ALT_ID`)
) ENGINE=INNODB DEFAULT CHARSET=utf8mb3 COMMENT='TABLE TO STORE EACH ACCOUNT''S CONFIGURED ALERTS DETAILS';

